import json
from datetime import datetime

def format_request_log(method: str, path: str, headers: dict, body: str) -> str:
    log_entry = {
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "method": method,
        "path": path,
        "headers": {key: value for key, value in headers.items() if key.lower() != 'Authorization'},
        "body": body
    }
    return json.dumps(log_entry)

import httpx

def format_request_log(method: str, path: str, headers: dict, body: str) -> str:
    sensitive_headers = {'authorization', 'cookie', 'set-cookie'}
    masked_headers = {k: (v if k.lower() not in sensitive_headers else '[REDACTED]') for k, v in headers.items()}
    headers_str = ', '.join(f'{k}: {v}' for k, v in masked_headers.items())
    return f'{method} {path} | Headers: {{{headers_str}}} | Body: {body}'

